import Foundation

/// RFC 9457 Problem Details returned for every error response.
public struct ServiceErrorResponse: Codable, Hashable, Sendable {
    /// A URI reference that identifies the problem type.
    public let type: String
    /// A short, human-readable summary of the problem type.
    public let title: String
    /// The HTTP status code generated by the origin server for this occurrence of the problem.
    public let status: Int
    /// A human-readable explanation specific to this occurrence of the problem.
    public let detail: String?
    /// A URI reference that identifies the specific occurrence of the problem.
    public let instance: String?
    /// Service-specific error code.
    public let code: Int?
    /// Field-level validation failures.
    public let errors: [ServiceErrorResponseErrorsItem]?
    /// Additional properties that are not explicitly defined in the schema
    public let additionalProperties: [String: JSONValue]

    public init(
        type: String,
        title: String,
        status: Int,
        detail: String? = nil,
        instance: String? = nil,
        code: Int? = nil,
        errors: [ServiceErrorResponseErrorsItem]? = nil,
        additionalProperties: [String: JSONValue] = .init()
    ) {
        self.type = type
        self.title = title
        self.status = status
        self.detail = detail
        self.instance = instance
        self.code = code
        self.errors = errors
        self.additionalProperties = additionalProperties
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.type = try container.decode(String.self, forKey: .type)
        self.title = try container.decode(String.self, forKey: .title)
        self.status = try container.decode(Int.self, forKey: .status)
        self.detail = try container.decodeIfPresent(String.self, forKey: .detail)
        self.instance = try container.decodeIfPresent(String.self, forKey: .instance)
        self.code = try container.decodeIfPresent(Int.self, forKey: .code)
        self.errors = try container.decodeIfPresent([ServiceErrorResponseErrorsItem].self, forKey: .errors)
        self.additionalProperties = try decoder.decodeAdditionalProperties(using: CodingKeys.self)
    }

    public func encode(to encoder: Encoder) throws -> Void {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try encoder.encodeAdditionalProperties(self.additionalProperties)
        try container.encode(self.type, forKey: .type)
        try container.encode(self.title, forKey: .title)
        try container.encode(self.status, forKey: .status)
        try container.encodeIfPresent(self.detail, forKey: .detail)
        try container.encodeIfPresent(self.instance, forKey: .instance)
        try container.encodeIfPresent(self.code, forKey: .code)
        try container.encodeIfPresent(self.errors, forKey: .errors)
    }

    /// Keys for encoding/decoding struct properties.
    enum CodingKeys: String, CodingKey, CaseIterable {
        case type
        case title
        case status
        case detail
        case instance
        case code
        case errors
    }
}